pub fn verify_oidc_id_token(claims: Rc<OidcIdTokenClaims>, signature: Rc<OidcIdTokenSignature>, policy: Rc<OidcIdTokenVerdictPolicy>) -> Rc<OidcIdTokenVerdict> {
    match (*signature.clone()).clone() {
    OidcIdTokenSignature::OidcIdTokenSignatureRefused { reason: r, .. } => Rc::new(OidcIdTokenVerdict::OidcIdTokenRefused {
    cause: Rc::new(OidcIdTokenRefusal::OidcIdTokenSignatureRefusal {
    reason: r.clone(),
}),
}),
    OidcIdTokenSignature::OidcIdTokenSignatureVerified { key: _, .. } => if (claims.issuer.clone() != policy.expected_issuer.clone()) {
        Rc::new(OidcIdTokenVerdict::OidcIdTokenRefused {
    cause: Rc::new(OidcIdTokenRefusal::OidcIdTokenIssuerMismatch {
    presented: claims.issuer.clone(),
    expected: policy.expected_issuer.clone(),
}),
})
    } else {
        if !oidc_audience_admitted(claims.audience.clone(), policy.admitted_audiences.clone()) {
            Rc::new(OidcIdTokenVerdict::OidcIdTokenRefused {
    cause: Rc::new(OidcIdTokenRefusal::OidcIdTokenAudienceNotAdmitted {
    presented: claims.audience.clone(),
    admitted: policy.admitted_audiences.clone(),
}),
})
        } else {
            match (*oidc_expiry_check(claims.expires_at.clone(), policy.observed_at.clone())).clone() {
    OidcExpiryCheck::OidcExpiryExpired => Rc::new(OidcIdTokenVerdict::OidcIdTokenRefused {
    cause: Rc::new(OidcIdTokenRefusal::OidcIdTokenExpired {
    expires_at: claims.expires_at.clone(),
    observed_at: policy.observed_at.clone(),
}),
}),
    OidcExpiryCheck::OidcExpiryNotWholeSeconds { reason: r, .. } => Rc::new(OidcIdTokenVerdict::OidcIdTokenRefused {
    cause: Rc::new(OidcIdTokenRefusal::OidcIdTokenExpiryNotWholeSeconds {
    reason: r.clone(),
}),
}),
    OidcExpiryCheck::OidcExpiryNotExpired => verify_oidc_id_token_past_expiry(claims.clone(), policy.clone()),
}
        }
    },
}
}

pub fn verify_oidc_id_token_past_expiry(claims: Rc<OidcIdTokenClaims>, policy: Rc<OidcIdTokenVerdictPolicy>) -> Rc<OidcIdTokenVerdict> {
    match policy.expected_nonce.clone() {
    Some(expected_nonce) => if oidc_nonce_matches(claims.nonce.clone(), expected_nonce.clone()) {
        verify_oidc_id_token_past_nonce(claims.clone(), policy.clone())
    } else {
        Rc::new(OidcIdTokenVerdict::OidcIdTokenRefused {
    cause: Rc::new(OidcIdTokenRefusal::OidcIdTokenNonceMismatch {
    presented: claims.nonce.clone(),
    expected: expected_nonce.clone(),
}),
})
    },
    std::option::Option::None => verify_oidc_id_token_past_nonce(claims.clone(), policy.clone()),
}
}

pub fn verify_oidc_id_token_past_nonce(claims: Rc<OidcIdTokenClaims>, policy: Rc<OidcIdTokenVerdictPolicy>) -> Rc<OidcIdTokenVerdict> {
    if (claims.standard.email_verified.clone() == Some(true)) {
        verify_oidc_id_token_past_email(claims.clone(), policy)
    } else {
        Rc::new(OidcIdTokenVerdict::OidcIdTokenRefused {
    cause: Rc::new(OidcIdTokenRefusal::OidcIdTokenEmailUnverified {
    email_verified: claims.standard.email_verified.clone(),
}),
})
    }
}

pub fn verify_oidc_id_token_past_email(claims: Rc<OidcIdTokenClaims>, policy: Rc<OidcIdTokenVerdictPolicy>) -> Rc<OidcIdTokenVerdict> {
    match claims.hosted_domain.clone() {
    Some(hd) => if (hd.clone() == policy.expected_hosted_domain.clone()) {
        Rc::new(OidcIdTokenVerdict::OidcIdTokenVerified {
    claims: claims.clone(),
})
    } else {
        Rc::new(OidcIdTokenVerdict::OidcIdTokenRefused {
    cause: Rc::new(OidcIdTokenRefusal::OidcIdTokenHostedDomainMismatch {
    presented: Some(hd.clone()),
    expected: policy.expected_hosted_domain.clone(),
}),
})
    },
    std::option::Option::None => Rc::new(OidcIdTokenVerdict::OidcIdTokenRefused {
    cause: Rc::new(OidcIdTokenRefusal::OidcIdTokenHostedDomainMismatch {
    presented: std::option::Option::None,
    expected: policy.expected_hosted_domain.clone(),
}),
}),
}
}

pub fn oidc_nonce_matches(presented: Option<String>, expected: String) -> bool {
    match presented.clone() {
    Some(p) => (p.clone() == expected.clone()),
    std::option::Option::None => false,
}
}

